import urllib.request
import json
import re

def fetch_url(url):
    req = urllib.request.Request(url, headers={'User-Agent': 'Mozilla/5.0 (Windows NT 10.0; Win64; x64)'})
    with urllib.request.urlopen(req) as resp:
        return resp.read().decode('utf-8', errors='ignore')

print("=== 1. Checking punkpeye/awesome-mcp-servers ===")
awesome_readme = fetch_url('https://raw.githubusercontent.com/punkpeye/awesome-mcp-servers/main/README.md')
gemini_lines = []
for line in awesome_readme.split('\n'):
    if re.search(r'gemini|google', line, re.I) and '[' in line and ']' in line:
        gemini_lines.append(line)

print(f"Found {len(gemini_lines)} lines mentioning Gemini or Google:")
for l in gemini_lines:
    print("-", l)

print("\n=== 2. Checking modelcontextprotocol/servers ===")
try:
    mcp_servers_repo = json.loads(fetch_url('https://api.github.com/repos/modelcontextprotocol/servers/contents/src'))
    print("Directories in modelcontextprotocol/servers/src:")
    for item in mcp_servers_repo:
        if 'google' in item['name'].lower() or 'gemini' in item['name'].lower():
            print(" -> MATCH:", item['name'], item['html_url'])
        else:
            print("   ", item['name'])
except Exception as e:
    print("Error querying modelcontextprotocol/servers:", e)

